package com.lovemaptually.service;
import com.lovemaptually.common.ApiException;import com.lovemaptually.dto.request.CreateReviewRequest;import com.lovemaptually.dto.response.*;import com.lovemaptually.entity.*;import com.lovemaptually.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.OffsetDateTime;import java.util.*;import static com.lovemaptually.entity.Enums.*;
@Service @RequiredArgsConstructor
public class ReviewService {private final ReviewRepository reviews;private final ReviewTagRepository reviewTags;private final TagRepository tags;private final PlaceRepository places;private final UserRepository users;private final RelationGroupRepository groups;private final GroupPlaceRepository groupPlaces;private final GroupMemberRepository members;private final AccessService access;private final JdbcClient db;
 private static final Map<String,String[]> KEYWORDS=Map.ofEntries(Map.entry("조용함",new String[]{"조용","한적"}),Map.entry("대화",new String[]{"대화","얘기"}),Map.entry("웨이팅",new String[]{"웨이팅","기다"}),Map.entry("맵기",new String[]{"맵","매운"}),Map.entry("단맛",new String[]{"달","단맛"}),Map.entry("양",new String[]{"푸짐","양이"}),Map.entry("뷰",new String[]{"뷰","전망"}),Map.entry("주차",new String[]{"주차"}),Map.entry("서비스",new String[]{"친절","서비스"}),Map.entry("가성비",new String[]{"가성비","값어치"}),Map.entry("데이트",new String[]{"데이트"}),Map.entry("사진",new String[]{"사진","포토"}));
 @Transactional public ReviewResponse create(long uid,CreateReviewRequest b){if(b.rating()<1||b.rating()>5)throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"RATING_OUT_OF_RANGE","별점은 1~5 범위여야 합니다");Place place=places.findById(b.placeId()).orElseThrow(()->notFound("PLACE_NOT_FOUND","장소를 찾을 수 없습니다"));if(b.withGroupId()!=null)access.member(b.withGroupId(),uid);if(reviews.existsByUserUserIdAndPlacePlaceIdAndVisitedOn(uid,b.placeId(),b.visitedOn()))throw new ApiException(HttpStatus.CONFLICT,"REVIEW_DUPLICATED","같은 날 같은 장소에 이미 리뷰를 남겼습니다");Review r=reviews.saveAndFlush(Review.builder().user(users.getReferenceById(uid)).place(place).withGroup(b.withGroupId()==null?null:groups.getReferenceById(b.withGroupId())).visitedOn(b.visitedOn()).rating(b.rating().shortValue()).content(b.content()).tagStatus(TagStatus.PENDING).build());try{extract(r,b.content());r.setTagStatus(TagStatus.COMPLETED);reviews.flush();recompute(uid,b.placeId(),b.withGroupId());}catch(Exception e){r.setTagStatus(TagStatus.FAILED);}return response(r,uid,true);}
 @Transactional(readOnly=true) public ReviewResponse get(long id,long uid,boolean ownerOnly){Review r=reviews.findDetailByReviewId(id).orElseThrow(()->notFound("REVIEW_NOT_FOUND","리뷰를 찾을 수 없습니다"));return response(r,uid,ownerOnly);}
 @Transactional(readOnly=true) public GroupReviewsResponse groupReviews(long gid,long pid,long uid){access.member(gid,uid);if(!places.existsById(pid))throw notFound("PLACE_NOT_FOUND","장소를 찾을 수 없습니다");List<Review> rs=reviews.findAllByWithGroupGroupIdAndPlacePlaceIdOrderByVisitedOnDesc(gid,pid);List<ReviewSummaryResponse> mine=rs.stream().filter(r->r.getUser().getUserId()==uid).map(this::summary).toList(),others=rs.stream().filter(r->r.getUser().getUserId()!=uid).map(this::summary).toList();long active=members.countByGroupGroupIdAndLeftAtIsNull(gid),reviewers=rs.stream().map(r->r.getUser().getUserId()).distinct().count();boolean locked=reviewers<active;PlaceLabelResponse l=label(gid,pid);return new GroupReviewsResponse(l==null?null:l.label(),l==null?0:l.reviewedCount(),l==null?0:l.likedCount(),mine.isEmpty()?null:mine.getFirst(),locked?List.of():others,locked,locked?"다른 구성원이 리뷰를 남기면 함께 공개됩니다":null);}
 private ReviewResponse response(Review r,long uid,boolean ownerOnly){if(ownerOnly&&!r.getUser().getUserId().equals(uid))throw new ApiException(HttpStatus.FORBIDDEN,"REVIEW_ACCESS_DENIED","내 리뷰가 아닙니다");List<ExtractedTagResponse> ts=reviewTags.findAllByReviewReviewId(r.getReviewId()).stream().map(rt->new ExtractedTagResponse(rt.getTag().getName(),word(rt.getFactValue(),rt.getTag()),word(rt.getWantValue(),rt.getTag()),rt.getEvidenceText())).toList();PlaceLabelResponse l=r.getWithGroup()==null?null:label(r.getWithGroup().getGroupId(),r.getPlace().getPlaceId());return new ReviewResponse(r.getReviewId(),r.getPlace().getPlaceId(),r.getVisitedOn(),r.getRating(),r.getContent(),r.getTagStatus().name(),ts,l,r.getCreatedAt());}
 private void extract(Review r,String content){String lower=content.toLowerCase();for(var e:KEYWORDS.entrySet()){String hit=Arrays.stream(e.getValue()).filter(lower::contains).findFirst().orElse(null);if(hit==null)continue;Tag tag=tags.findByName(e.getKey()).orElseThrow();boolean neg=lower.contains("안 "+hit)||lower.contains(hit+" 없")||lower.contains(hit+"지 않");AttrLevel fact=neg?AttrLevel.LOW:AttrLevel.HIGH,want=e.getKey().equals("웨이팅")?AttrLevel.LOW:fact;reviewTags.save(ReviewTag.builder().review(r).tag(tag).factValue(fact).wantValue(want).evidenceText(hit).build());}}
 private void recompute(long uid,long pid,Long gid){db.sql("DELETE FROM user_tags WHERE user_id=:u").param("u",uid).update();db.sql("INSERT INTO user_tags(user_id,tag_id,want_high_count,want_low_count) SELECT r.user_id,rt.tag_id,count(*) FILTER(WHERE want_value='HIGH'),count(*) FILTER(WHERE want_value='LOW') FROM reviews r JOIN review_tags rt USING(review_id) WHERE r.user_id=:u AND want_value IS NOT NULL GROUP BY r.user_id,rt.tag_id").param("u",uid).update();db.sql("DELETE FROM place_tags WHERE place_id=:p").param("p",pid).update();db.sql("INSERT INTO place_tags(place_id,tag_id,fact_high_count,fact_low_count) SELECT :p,x.tag_id,count(*) FILTER(WHERE fact_value='HIGH'),count(*) FILTER(WHERE fact_value='LOW') FROM (SELECT DISTINCT ON(r.user_id,rt.tag_id) r.user_id,rt.tag_id,rt.fact_value FROM reviews r JOIN review_tags rt USING(review_id) WHERE r.place_id=:p AND fact_value IS NOT NULL ORDER BY r.user_id,rt.tag_id,r.visited_on DESC,r.review_id DESC)x GROUP BY x.tag_id").param("p",pid).update();if(gid!=null){GroupPlace gp=groupPlaces.findByGroupGroupIdAndPlacePlaceId(gid,pid).orElseGet(()->groupPlaces.save(GroupPlace.builder().group(groups.getReferenceById(gid)).place(places.getReferenceById(pid)).addedBy(users.getReferenceById(uid)).reviewedCount(0).likedCount(0).build()));Map<String,Object>c=db.sql("SELECT count(*) reviewed,count(*) FILTER(WHERE rating>=4) liked FROM (SELECT DISTINCT ON(user_id) user_id,rating FROM reviews WHERE with_group_id=:g AND place_id=:p ORDER BY user_id,visited_on DESC,review_id DESC)x").param("g",gid).param("p",pid).query().singleRow();int reviewed=((Number)c.get("reviewed")).intValue(),liked=((Number)c.get("liked")).intValue();gp.setReviewedCount(reviewed);gp.setLikedCount(liked);gp.setLabel(liked==0?PlaceLabel.ON_HOLD:liked==reviewed?PlaceLabel.ALL_LIKED:PlaceLabel.MIXED);gp.setLabelUpdatedAt(OffsetDateTime.now());}}
 private PlaceLabelResponse label(long gid,long pid){return groupPlaces.findByGroupGroupIdAndPlacePlaceId(gid,pid).map(g->new PlaceLabelResponse(g.getLabel()==null?null:g.getLabel().name(),g.getReviewedCount(),g.getLikedCount())).orElse(null);}private String word(AttrLevel v,Tag t){return v==null?null:v==AttrLevel.HIGH?t.getHighLabel():t.getLowLabel();}private ReviewSummaryResponse summary(Review r){return new ReviewSummaryResponse(r.getReviewId(),r.getUser().getUserId(),r.getUser().getNickname(),r.getRating(),r.getContent(),r.getVisitedOn());}private ApiException notFound(String code,String msg){return new ApiException(HttpStatus.NOT_FOUND,code,msg);}}
